import { useLocation } from "react-router-dom";
import GameCard from "../components/GameCard";
import { useGames } from "../hooks/useGames";

function useQuery() {
  return new URLSearchParams(useLocation().search);
}

export default function SearchPage() {
  const q = useQuery().get("q")?.toLowerCase() || "";
  const { games, loading } = useGames();

  if (loading) {
    return <h2 className="loading-text">Loading Games...</h2>;
  }

  const filteredGames = games.filter(g => 
    g.Name.toLowerCase().includes(q)
  );

  return (
    <div className="search-page">
      <h2 className="page-title">Search: "{q}"</h2>
      {filteredGames.length === 0 ? (
        <p className="no-results">No games found! Try another search.</p>
      ) : (
        <div className="grid">
          {filteredGames.map(g => <GameCard key={g._id} game={g} />)}
        </div>
      )}
    </div>
  );
}
